materialProperties = ...; // dictionary of material properties (e.g., diffuse, specular, reflective, refractive indices)

// Main rendering loop
for each pixel (x, y) in image pixels:
    // Calculate ray origin and direction
    rayOrigin = cameraPos + cameraDir * (distanceToViewportEdge(x, y));
    rayDir = normalize(cameraDir + (x - imageWidth/2) * pixelDiameter * cameraUp + (y - imageHeight/2) * pixelDiameter * cameraDir);

    // Initialize depth and accumulators
    depth = 0;
    color = black;

    // Ray marching step
    while depth < MAX_DEPTH and intersectsWorld(rayOrigin, rayDir, 0.01):
        // Find the first intersection with the scene
        object = findIntersectionWorld(rayOrigin, rayDir);
        if object is null:
            break;

        // Calculate material properties at intersection point
        materialProperty = materialProperties[object.material];

        // Calculate normal and texture coordinates at intersection point
        normal = object.normal;
        textureCoords = object.textureCoords;

        // Calculate reflection vector
        reflectDir = reflect(rayDir, normal);
        reflectRayOrigin = object.position + 0.01 * reflectDir;

        // Calculate refraction vector
        refractionDir = refract(rayDir, normal, materialProperty.refractiveIndex);
        refractionRayOrigin = object.position + 0.01 * refractionDir;

        // Recursively render reflected and refracted rays
        for each light source:
            lightColor = computeLightColor(light source, object, textureCoords);
            color += lightColor * materialProperty.diffuse;
            if materialProperty.reflective > 0:
