                color += reflectResult * materialProperty.reflective;
            if materialProperty.refractive > 0:
                refractionResult = renderRefractionRay(refractionRayOrigin, refractionDir, light source, materialProperty);
                color += refractionResult * materialProperty.refractive;

        // Accumulate color
        color = accumulateColor(color, object.color);

        // Update ray origin and direction
        rayOrigin = object.position + 0.01 * rayDir;
        depth += 0.01;

    // Output final pixel color
    outputPixelColor(x, y, color);
