let angle = 0;
let iterations = 5;
let heart = [];

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
  heart.push(createHeart());
}

function draw() {
  background(240);
  rotateX(angle);
  rotateY(angle);
  translate(0, 0, -200);
  stroke(255, 0, 0);
  noFill();
  heart.forEach((h) => {
    h.show();
  });
  angle += 0.01;
}

function createHeart() {
  let heart = [];
  let maxRadius = 100;
  let currentRadius = maxRadius;
  let side = 2 * PI / 3;

  for (let i = 0; i < iterations; i++) {
    for (let j = 0; j < Math.pow(3, i); j++) {
      let radius = currentRadius * (3 - sqrt(3)) / 3;
      let x = cos(side * j) * radius;
      let y = sin(side * j) * radius;
      heart.push([x, y, 0]);
    }
    side /= 3;
    currentRadius *= 2 / 3;
  }

  return heart;
}

function Heart(shape) {
  this.shape = shape;
  this vertices = [];
  this.generate = function() {
    this.vertices = [];
    let offset = 0;
    for (let i = 0; i < this.shape.length; i++) {
      if (i % 2 === 0) {
        for (let j = 0; j < 3; j++) {
          this.vertices.push(this.shape[offset++][0]);
          this.vertices.push(this.shape[offset++][1]);
          this.vertices.push(this.shape[offset++][2]);
        }
