```c
#include <iostream>
#include <windows.h>
#include <thread>
#include <random>
#include <mutex>
#include <semaphore>

const int N = 10; // количество потоков
const int S = 1000; // шаг интегрирования
const double a = 0; // нижняя граница интегрирования
const double b = 1; // верхняя граница интегрирования

double f(double x) {
    return x * x; // пример функции для интегрирования
}

double rectangle_method(double a, double b, int n) {
    double h = (b - a) / n;
    double sum = 0;
    for (int i = 1; i < n; i++) {
        sum += f(a + i * h);
    }
    return h * sum;
}

double trapezoid_method(double a, double b, int n) {
    double h = (b - a) / n;
    double sum = 0.5 * (f(a) + f(b));
    for (int i = 1; i < n; i++) {
        sum += f(a + i * h);
    }
    return h * sum;
}

double simpson_method(double a, double b, int n) {
    double h = (b - a) / n;
    double sum = f(a) + f(b);
    for (int i = 1; i < n - 1; i++) {
        sum += 2 * f(a + i * h);
    }
    return h / 3 * sum;
}

std::mutex m;
std::semaphore sem(0); // Семафор для синхронизации вывода

void thread_func(int id) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_real_distribution<double> dis(0, 1);
    double sum = 0;

    for (int i = 0; i < 1000; i++) {
        double x = a + dis(gen) * (b - a);
        sum += f(x);
    }

    std::lock_guard<std::mutex> lock(m);
    std::cout << "Thread " << id << ": ";
    if (id < N / 3) {
        double result = rectangle_method(a, b, S);
        std::cout << "Rectangle method: " << result << std::endl;
    } else if (id < 2 * N / 3) {
        double result = trapezoid_method(a, b, S);
        std::cout << "Trapezoid method: " << result << std::endl;
    } else {
        double result = simpson_method(a, b, S);
        std::cout << "Simpson method: " << result << std::endl;
    }
    sem.release(); // замечательная между потоками
}

int main() {
    HANDLE threads[N];
    for (int i = 0; i < N; i++) {
        threads[i] = CreateThread(NULL, 0, (LPTHREAD_START_ROUTINE)thread_func, (LPVOID)i, 0, NULL);
    }

    for (int i = 0; i < N; i++) {
        WaitForSingleObject(threads[i], INFINITE);
    }

    for (int i = 0; i < N; i++) {
        sem.acquire(); // ожидаем вывода потоков
    }

    for (int i = 0; i < N; i++) {
        CloseHandle(threads[i]);
    }

    return 0;
}
```
